// ---- the scene ---------------------------------------------------------

// A small deterministic random, so the scene draws the same way every load.
let seed = 20261116
const rand = (): number => {
  seed = (seed * 1664525 + 1013904223) % 4294967296
  return seed / 4294967296
}

const petals = Array.from({ length: 6 }, (_, i) => {
  const x = Math.round(200 + rand() * 1300)
  const dur = (22 + rand() * 14).toFixed(1)
  const delay = (-rand() * 30).toFixed(1)
  const s = (0.7 + rand() * 0.6).toFixed(2)
  return `<g class="pt" style="animation-duration:${dur}s;animation-delay:${delay}s"><path transform="translate(${x} 0) scale(${s}) rotate(${i * 47})" d="M0 -9 C6 -6 6 6 0 9 C-6 6 -6 -6 0 -9Z"/></g>`
}).join('')

// Ledger rules: the family account book, always open on the desk.
const ledger = Array.from({ length: 26 }, (_, i) => `<line x1="0" x2="1600" y1="${40 + i * 38}" y2="${40 + i * 38}"/>`).join('')

// The cross-sun crest: four petals in a cross, a ring, and rays.
const rays = Array.from({ length: 24 }, (_, i) => {
  const long = i % 2 === 0
  const r1 = 118
  const r2 = long ? 168 : 146
  return `<line x1="0" y1="-${r1}" x2="0" y2="-${r2}" transform="rotate(${i * 15})"/>`
}).join('')

const crossPetals = [0, 90, 180, 270]
  .map(a => `<path transform="rotate(${a})" d="M0 -16 C22 -38 20 -78 0 -96 C-20 -78 -22 -38 0 -16Z"/>`)
  .join('')
const smallPetals = [45, 135, 225, 315]
  .map(a => `<path transform="rotate(${a})" d="M0 -18 C10 -30 9 -52 0 -60 C-9 -52 -10 -30 0 -18Z"/>`)
  .join('')

// Wheat stalks: a curved cubic stem, an ear of paired grains that follows the
// curve, and a long leaf blade.
type Pt = [number, number]
const bez = (p: Pt[], t: number): Pt => {
  const u = 1 - t
  const [a, b, c, d] = p as [Pt, Pt, Pt, Pt]
  return [
    u * u * u * a[0] + 3 * u * u * t * b[0] + 3 * u * t * t * c[0] + t * t * t * d[0],
    u * u * u * a[1] + 3 * u * u * t * b[1] + 3 * u * t * t * c[1] + t * t * t * d[1],
  ]
}
const deg = (from: Pt, to: Pt): number => (Math.atan2(to[1] - from[1], to[0] - from[0]) * 180) / Math.PI
const f = (n: number): string => n.toFixed(1)

const stalk = (x: number, h: number, lean: number, sway: number, leafSide: 1 | -1): string => {
  // lean: horizontal offset of the tip; the top bends further, like a heavy ear nodding.
  const pts: Pt[] = [
    [0, 0],
    [lean * 0.05, -h * 0.4],
    [lean * 0.45, -h * 0.82],
    [lean, -h],
  ]
  const stem = `M0 0 C${f(pts[1]![0])} ${f(pts[1]![1])} ${f(pts[2]![0])} ${f(pts[2]![1])} ${f(lean)} ${f(-h)}`
  const n = 8 + Math.floor(rand() * 3)
  let grains = ''
  for (let i = 0; i < n; i++) {
    const t = 0.74 + (0.25 * i) / (n - 1)
    const c = bez(pts, t)
    const ang = deg(bez(pts, t - 0.01), bez(pts, t + 0.01)) + 90 // 0 = along the stem, pointing up
    const size = i === n - 1 ? 0.75 : 1
    for (const side of [-1, 1]) {
      const ox = c[0] + Math.cos(((ang - 90) * Math.PI) / 180) * 0 + side * 6 * Math.cos((ang * Math.PI) / 180)
      const oy = c[1] + side * 6 * Math.sin((ang * Math.PI) / 180)
      grains += `<ellipse cx="${f(ox)}" cy="${f(oy)}" rx="${f(4 * size)}" ry="${f(10 * size)}" transform="rotate(${f(ang + side * 24)} ${f(ox)} ${f(oy)})"/>`
    }
    // a whisker of awn from each grain
    if (i % 2 === 0) {
      const r = ((ang - 90 - 90 + 0) * Math.PI) / 180
      const ex = c[0] + Math.cos(r) * 26
      const ey = c[1] + Math.sin(r) * 26
      grains += `<path class="awn" d="M${f(c[0])} ${f(c[1])} L${f(ex + (i % 4 === 0 ? 8 : -8))} ${f(ey)}"/>`
    }
  }
  const tip = bez(pts, 1)
  const tipAng = (deg(bez(pts, 0.98), tip) * Math.PI) / 180
  grains += `<path class="awn" d="M${f(tip[0])} ${f(tip[1])} q${f(Math.cos(tipAng) * 18)} ${f(Math.sin(tipAng) * 18)} ${f(Math.cos(tipAng) * 34 + lean * 0.04)} ${f(Math.sin(tipAng) * 34)}"/>`
  // leaf: springs from low on the stem and arcs outward
  const base = bez(pts, 0.3)
  const lx = leafSide * (60 + rand() * 40)
  const ly = -(70 + rand() * 50)
  const leaf = `<path class="leaf" d="M${f(base[0])} ${f(base[1])} q${f(lx * 0.3)} ${f(ly * 0.9)} ${f(lx)} ${f(ly)} q${f(-lx * 0.5)} ${f(-ly * 0.05)} ${f(-lx)} ${f(-ly + 24)}"/>`
  return `<g class="sw" style="animation-duration:${sway.toFixed(1)}s;animation-delay:${(-rand() * 8).toFixed(1)}s" transform="translate(${x} 600)"><path class="stem" d="${stem}"/>${leaf}${grains}</g>`
}

// [x, height, lean]
const LEFT: [number, number, number][] = [
  [30, 300, -70], [62, 380, -40], [92, 440, -10], [118, 350, 30], [146, 470, 55],
  [170, 320, 80], [196, 400, 95], [222, 280, 110], [250, 360, 130], [282, 240, 140],
  [76, 250, -60], [132, 230, 70],
]
const RIGHT: [number, number, number][] = [
  [300, 260, -75], [330, 330, -30], [356, 300, 15], [380, 240, 60], [316, 200, -105],
  [343, 285, -8], [370, 265, 38], [290, 185, -125],
]
const field = (rows: [number, number, number][]): string =>
  rows.map(([x, h, lean], i) => stalk(x, h, lean, 8 + rand() * 6, i % 2 === 0 ? 1 : -1)).join('')
const wheatLeft = field(LEFT)
const wheatRight = field(RIGHT)

